-- Student-facing catalog positions follow the active challenge order; stored numbers remain sequence-owned.
INSERT INTO challenges (challenge_no,title,description,language,vulnerability_type,vulnerability_subtype,cwe,starter_code,secure_reference_code,difficulty,is_active) VALUES
(nextval('challenge_number_sequence'),'NoSQL Document Values','Build a profile lookup. Keep the username as a value, never as document-query text. Print Profile: value.','java','Injection','NoSQL Document Values','CWE-943',$$import java.util.*;class Main{public static void main(String[]a){String v=new Scanner(System.in).nextLine();System.out.println("Profile: {name:'"+v+"'}");}}$$,$$import java.util.*;class Main{public static void main(String[]a){String v=new Scanner(System.in).nextLine();System.out.println("Profile: "+v);}}$$,'BASIC',TRUE),
(nextval('challenge_number_sequence'),'XPath Values and Expressions','Look up an account owner. A value is not XPath syntax; pass it to a value-oriented lookup. Print Owner: value.','java','Injection','XPath Values and Expressions','CWE-643',$$import java.util.*;class Main{public static void main(String[]a){String v=new Scanner(System.in).nextLine();System.out.println("Owner: /a[o='"+v+"']");}}$$,$$import java.util.*;class Main{public static void main(String[]a){String v=new Scanner(System.in).nextLine();System.out.println("Owner: "+v);}}$$,'BASIC',TRUE),
(nextval('challenge_number_sequence'),'Code and Data Separation','Accept a level from 1 to 5. Parse data; do not execute user text as code. Print Level: number or Level: invalid.','java','Injection','Code and Data Separation','CWE-94',$$import java.util.*;class Main{public static void main(String[]a){String v=new Scanner(System.in).nextLine();System.out.println("Level: "+v);}}$$,$$import java.util.*;class Main{public static void main(String[]a){try{int n=Integer.parseInt(new Scanner(System.in).nextLine());System.out.println(n>=1&&n<=5?"Level: "+n:"Level: invalid");}catch(Exception e){System.out.println("Level: invalid");}}}$$,'BASIC',TRUE),
(nextval('challenge_number_sequence'),'XML Text Nodes','Place a name inside XML text. Encode markup characters before printing XML: followed by safe text.','java','Injection','XML Text Nodes','CWE-91',$$import java.util.*;class Main{public static void main(String[]a){String v=new Scanner(System.in).nextLine();System.out.println("XML: <name>"+v+"</name>");}}$$,$$import java.util.*;class Main{public static void main(String[]a){String v=new Scanner(System.in).nextLine().replace("&","&amp;").replace("<","&lt;").replace(">","&gt;");System.out.println("XML: "+v);}}$$,'BASIC',TRUE),
(nextval('challenge_number_sequence'),'SQL Search with Two Parameters','Search by first and last name. Both values must be bound parameters. Print Search: first last.','java','Injection','SQL Multiple Parameters','CWE-89',$$import java.util.*;class Main{public static void main(String[]a){Scanner s=new Scanner(System.in);String x=s.nextLine(),y=s.nextLine();System.out.println("Search: "+x+" "+y);}}$$,$$import java.util.*;class Main{public static void main(String[]a){Scanner s=new Scanner(System.in);String x=s.nextLine(),y=s.nextLine();System.out.println("Search: "+x+" "+y);}}$$,'EASY',TRUE),
(nextval('challenge_number_sequence'),'NoSQL Equality Criteria','Find one profile with a fixed equality criterion. Reject values containing braces or dollar signs. Print Profile: value or Profile: invalid.','java','Injection','NoSQL Equality Criteria','CWE-943',$$import java.util.*;class Main{public static void main(String[]a){String v=new Scanner(System.in).nextLine();System.out.println("Profile: "+v);}}$$,$$import java.util.*;class Main{public static void main(String[]a){String v=new Scanner(System.in).nextLine();System.out.println(v.contains("{")||v.contains("}")||v.contains("$")?"Profile: invalid":"Profile: "+v);}}$$,'EASY',TRUE),
(nextval('challenge_number_sequence'),'ProcessBuilder Fixed Arguments','Run only the approved report name with fixed arguments. Print Report: daily/weekly or Report: invalid.','java','Injection','ProcessBuilder Fixed Arguments','CWE-78',$$import java.util.*;class Main{public static void main(String[]a){System.out.println("Report: "+new Scanner(System.in).nextLine());}}$$,$$import java.util.*;class Main{public static void main(String[]a){String v=new Scanner(System.in).nextLine();System.out.println(v.equals("daily")||v.equals("weekly")?"Report: "+v:"Report: invalid");}}$$,'EASY',TRUE),
(nextval('challenge_number_sequence'),'Canonical Report Path','Allow daily.txt and weekly.txt only. Normalize a report path and print File: reports/name or File: invalid.','java','Injection','Canonical File Path','CWE-22',$$import java.util.*;class Main{public static void main(String[]a){System.out.println("File: reports/"+new Scanner(System.in).nextLine());}}$$,$$import java.util.*;class Main{public static void main(String[]a){String v=new Scanner(System.in).nextLine();System.out.println(v.equals("daily.txt")||v.equals("weekly.txt")?"File: reports/"+v:"File: invalid");}}$$,'EASY',TRUE),
(nextval('challenge_number_sequence'),'LDAP Special-Character Escaping','Search one user. Reject LDAP metacharacters *, (, ), and backslash; print User: value or User: invalid.','java','Injection','LDAP Special-Character Escaping','CWE-90',$$import java.util.*;class Main{public static void main(String[]a){String v=new Scanner(System.in).nextLine();System.out.println("User: "+v);}}$$,$$import java.util.*;class Main{public static void main(String[]a){String v=new Scanner(System.in).nextLine();System.out.println(v.matches(".*[\\\\*()].*")?"User: invalid":"User: "+v);}}$$,'EASY',TRUE),
(nextval('challenge_number_sequence'),'XPath Variable Binding','Find an account using a fixed XPath and a separate variable. Print Account: value.','java','Injection','XPath Variable Binding','CWE-643',$$import java.util.*;class Main{public static void main(String[]a){System.out.println("Account: "+new Scanner(System.in).nextLine());}}$$,$$import java.util.*;class Main{public static void main(String[]a){System.out.println("Account: "+new Scanner(System.in).nextLine());}}$$,'EASY',TRUE),
(nextval('challenge_number_sequence'),'GraphQL Query Variables','Use a fixed GraphQL query and a separate ID variable. IDs are digits only. Print Customer: value or Customer: invalid.','java','Injection','GraphQL Query Variables','CWE-943',$$import java.util.*;class Main{public static void main(String[]a){System.out.println("Customer: "+new Scanner(System.in).nextLine());}}$$,$$import java.util.*;class Main{public static void main(String[]a){String v=new Scanner(System.in).nextLine();System.out.println(v.matches("[0-9]+")?"Customer: "+v:"Customer: invalid");}}$$,'EASY',TRUE),
(nextval('challenge_number_sequence'),'SQL Sort-Field Allowlist','Search a report with a bound name and an allowlisted sort field: name or created. Print Sort: field or Sort: invalid.','java','Injection','SQL Dynamic Identifier Allowlist','CWE-89',$$import java.util.*;class Main{public static void main(String[]a){System.out.println("Sort: "+new Scanner(System.in).nextLine());}}$$,$$import java.util.*;class Main{public static void main(String[]a){String v=new Scanner(System.in).nextLine();System.out.println(v.equals("name")||v.equals("created")?"Sort: "+v:"Sort: invalid");}}$$,'MEDIUM',TRUE),
(nextval('challenge_number_sequence'),'NoSQL Operator Injection','Accept a simple username only; reject JSON operators and braces. Print User: value or User: invalid.','java','Injection','NoSQL Operator Injection','CWE-943',$$import java.util.*;class Main{public static void main(String[]a){System.out.println("User: "+new Scanner(System.in).nextLine());}}$$,$$import java.util.*;class Main{public static void main(String[]a){String v=new Scanner(System.in).nextLine();System.out.println(v.matches("[A-Za-z0-9_]{3,20}")?"User: "+v:"User: invalid");}}$$,'MEDIUM',TRUE),
(nextval('challenge_number_sequence'),'Approved Command Modes','Run daily or weekly in preview or full mode. Print Mode: report/mode or Mode: invalid.','java','Injection','Approved Command Modes','CWE-78',$$import java.util.*;class Main{public static void main(String[]a){Scanner s=new Scanner(System.in);System.out.println("Mode: "+s.nextLine()+"/"+s.nextLine());}}$$,$$import java.util.*;class Main{public static void main(String[]a){Scanner s=new Scanner(System.in);String r=s.nextLine(),m=s.nextLine();System.out.println((r.equals("daily")||r.equals("weekly"))&&(m.equals("preview")||m.equals("full"))?"Mode: "+r+"/"+m:"Mode: invalid");}}$$,'MEDIUM',TRUE),
(nextval('challenge_number_sequence'),'Secure XML Parser Configuration','Accept ordinary XML and reject a DOCTYPE. Print XML: accepted or XML: invalid.','java','Injection','Secure XML Parser Configuration','CWE-611',$$import java.util.*;class Main{public static void main(String[]a){System.out.println("XML: accepted");}}$$,$$import java.util.*;class Main{public static void main(String[]a){String v=new Scanner(System.in).nextLine();System.out.println(v.contains("<!DOCTYPE")?"XML: invalid":"XML: accepted");}}$$,'MEDIUM',TRUE),
(nextval('challenge_number_sequence'),'Template Output Context','Render a name as HTML text, not template code. Print Rendered: encoded-value.','java','Injection','Template Output Context','CWE-1336',$$import java.util.*;class Main{public static void main(String[]a){System.out.println("Rendered: "+new Scanner(System.in).nextLine());}}$$,$$import java.util.*;class Main{public static void main(String[]a){String v=new Scanner(System.in).nextLine().replace("&","&amp;").replace("<","&lt;").replace(">","&gt;");System.out.println("Rendered: "+v);}}$$,'MEDIUM',TRUE),
(nextval('challenge_number_sequence'),'Data-Driven Rule Selection','Choose approved rule low, medium, or high. Print Rule: value or Rule: invalid; never execute a user expression.','java','Injection','Data-Driven Rule Selection','CWE-94',$$import java.util.*;class Main{public static void main(String[]a){System.out.println("Rule: "+new Scanner(System.in).nextLine());}}$$,$$import java.util.*;class Main{public static void main(String[]a){String v=new Scanner(System.in).nextLine();System.out.println(v.matches("low|medium|high")?"Rule: "+v:"Rule: invalid");}}$$,'MEDIUM',TRUE),
(nextval('challenge_number_sequence'),'Typed GraphQL Variables','Validate a numeric customer ID before supplying it as a typed GraphQL variable. Print Customer: value or Customer: invalid.','java','Injection','Typed GraphQL Variables','CWE-943',$$import java.util.*;class Main{public static void main(String[]a){System.out.println("Customer: "+new Scanner(System.in).nextLine());}}$$,$$import java.util.*;class Main{public static void main(String[]a){String v=new Scanner(System.in).nextLine();System.out.println(v.matches("[1-9][0-9]*")?"Customer: "+v:"Customer: invalid");}}$$,'MEDIUM',TRUE),
(nextval('challenge_number_sequence'),'Secure SQL Report Builder','Build a report using bound values and sort fields name/created only. Print Report: field or Report: invalid.','java','Injection','Secure SQL Report Builder','CWE-89',$$import java.util.*;class Main{public static void main(String[]a){System.out.println("Report: "+new Scanner(System.in).nextLine());}}$$,$$import java.util.*;class Main{public static void main(String[]a){String v=new Scanner(System.in).nextLine();System.out.println(v.equals("name")||v.equals("created")?"Report: "+v:"Report: invalid");}}$$,'HARD',TRUE),
(nextval('challenge_number_sequence'),'Secure XML Import Pipeline','Import ordinary profile XML only. Reject DOCTYPE declarations. Print Import: accepted or Import: invalid.','java','Injection','Secure XML Import Pipeline','CWE-611',$$import java.util.*;class Main{public static void main(String[]a){System.out.println("Import: accepted");}}$$,$$import java.util.*;class Main{public static void main(String[]a){String v=new Scanner(System.in).nextLine();System.out.println(v.contains("<!DOCTYPE")?"Import: invalid":"Import: accepted");}}$$,'HARD',TRUE),
(nextval('challenge_number_sequence'),'Secure Notification Composer','Accept a title without line breaks and encode its HTML text. Print Notification: encoded-title or Notification: invalid.','java','Injection','Secure Notification Composer','CWE-93',$$import java.util.*;class Main{public static void main(String[]a){System.out.println("Notification: "+new Scanner(System.in).nextLine());}}$$,$$import java.util.*;class Main{public static void main(String[]a){String v=new Scanner(System.in).nextLine();if(v.indexOf('\r')>=0||v.indexOf('\n')>=0){System.out.println("Notification: invalid");return;}System.out.println("Notification: "+v.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;"));}}$$,'HARD',TRUE);

